ALTER TABLE contacts DROP CONSTRAINT contacts_account_id_email_key;
CREATE TABLE products(LIKE records_base INCLUDING ALL, sku text NOT NULL, name text NOT NULL, category text NOT NULL, unit text NOT NULL DEFAULT 'piece', oe text NOT NULL DEFAULT '', fitment text NOT NULL DEFAULT '', fitment_status text NOT NULL DEFAULT 'unverified', source_id uuid NOT NULL REFERENCES sources, UNIQUE(business_entity_id,sku));
CREATE TABLE suppliers(LIKE records_base INCLUDING ALL, name text NOT NULL, email text NOT NULL DEFAULT '', evidence_id uuid NOT NULL REFERENCES sources);
CREATE TABLE purchase_rfqs(LIKE records_base INCLUDING ALL, rfq_id uuid NOT NULL REFERENCES rfqs, name text NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE TABLE supplier_responses(LIKE records_base INCLUDING ALL, purchase_rfq_id uuid NOT NULL REFERENCES purchase_rfqs, rfq_line_id uuid NOT NULL REFERENCES rfq_lines, supplier_id uuid NOT NULL REFERENCES suppliers, product_id uuid NOT NULL REFERENCES products, source_id uuid NOT NULL REFERENCES sources, price numeric(20,6) NOT NULL CHECK(price>=0), currency text NOT NULL, pack_qty numeric(20,6) CHECK(pack_qty>0), unit text NOT NULL, quality text NOT NULL, fee_scope text NOT NULL, moq numeric(20,6) NOT NULL CHECK(moq>0), valid_until timestamptz NOT NULL, selected boolean NOT NULL DEFAULT false, selection_reason text);
CREATE TABLE quotes(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, rfq_id uuid NOT NULL REFERENCES rfqs, revision integer NOT NULL DEFAULT 1, current_revision_id uuid);
CREATE TABLE quote_revisions(LIKE records_base INCLUDING ALL, quote_id uuid NOT NULL REFERENCES quotes, revision integer NOT NULL, recipient_id uuid NOT NULL REFERENCES contacts, currency text NOT NULL, incoterm text NOT NULL, place text NOT NULL, payment_terms text NOT NULL, valid_until timestamptz NOT NULL, status text NOT NULL DEFAULT 'draft', snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, amount numeric(20,6) NOT NULL, approved_by uuid REFERENCES users, approved_hash text, UNIQUE(quote_id,revision));
ALTER TABLE quotes ADD CONSTRAINT quotes_current_revision FOREIGN KEY(current_revision_id) REFERENCES quote_revisions;
CREATE TABLE orders(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, quote_revision_id uuid NOT NULL REFERENCES quote_revisions, confirmation_source_id uuid NOT NULL REFERENCES sources, purchase_reference text NOT NULL, status text NOT NULL DEFAULT 'confirmed', currency text NOT NULL, amount numeric(20,6) NOT NULL, UNIQUE(business_entity_id,account_id,purchase_reference));
CREATE TABLE order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders, product_id uuid NOT NULL REFERENCES products, quantity numeric(20,6) NOT NULL CHECK(quantity>0), shipped numeric(20,6) NOT NULL DEFAULT 0 CHECK(shipped>=0 AND shipped<=quantity), unit_price numeric(20,6) NOT NULL);
CREATE TABLE shipments(LIKE records_base INCLUDING ALL, order_id uuid NOT NULL REFERENCES orders, order_line_id uuid NOT NULL REFERENCES order_lines, event_key text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), tracking text NOT NULL, source_id uuid NOT NULL REFERENCES sources, UNIQUE(order_id,event_key));
CREATE TABLE receipts(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, amount numeric(20,6) NOT NULL CHECK(amount>0), currency text NOT NULL, source_id uuid NOT NULL REFERENCES sources, status text NOT NULL DEFAULT 'unverified', verified_by uuid REFERENCES users, event_key text NOT NULL, UNIQUE(business_entity_id,event_key));
CREATE TABLE allocations(LIKE records_base INCLUDING ALL, receipt_id uuid NOT NULL REFERENCES receipts, order_id uuid NOT NULL REFERENCES orders, amount numeric(20,6) NOT NULL CHECK(amount>0), event_key text NOT NULL, UNIQUE(receipt_id,event_key));
CREATE TABLE credit_policies(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL UNIQUE REFERENCES accounts, currency text NOT NULL, credit_limit numeric(20,6) NOT NULL CHECK(credit_limit>=0), valid_until timestamptz NOT NULL, approved_by uuid NOT NULL REFERENCES users);
CREATE TABLE credit_exposures(LIKE records_base INCLUDING ALL, account_id uuid NOT NULL REFERENCES accounts, order_id uuid NOT NULL UNIQUE REFERENCES orders, amount numeric(20,6) NOT NULL CHECK(amount>=0), segment text NOT NULL CHECK(segment IN ('commitment','receivable','released')), currency text NOT NULL);
